using System;\nusing System.Collections.Generic;\nusing System.Diagnostics;\nusing System.Threading;\n\nnamespace ClinicManager.MiddleTier\n{\n    /// <summary>\n    /// Service Manager - Orchestrates all middleware operations\n    /// Provides robust error handling, health monitoring, and graceful shutdown\n    /// Uses thread-safe patterns with timeouts to prevent deadlocks\n    /// </summary>\n    public class ServiceManager : IDisposable\n    {\n        private readonly List<IServiceComponent> _components;\n        private Timer? _healthCheckTimer;\n        private bool _isRunning;\n        private bool _disposed;\n        private const int HealthCheckInterval = 60000; // 60 seconds\n        private const int OperationTimeout = 30000; // 30 seconds\n        private readonly ReaderWriterLockSlim _stateLock = new ReaderWriterLockSlim();\n\n        public ServiceManager()\n        {\n            _components = new List<IServiceComponent>();\n            _isRunning = false;\n            _disposed = false;\n\n            // Initialize service components\n            InitializeComponents();\n        }\n\n        /// <summary>\n        /// Initialize all service components\n        /// </summary>\n        private void InitializeComponents()\n        {\n            try\n            {\n                // Add any middleware components here\n                _components.Add(new HealthMonitorComponent());\n                _components.Add(new ConfigurationComponent());\n                _components.Add(new LoggerComponent());\n            }\n            catch (Exception ex)\n            {\n                Debug.WriteLine($\"Error initializing components: {ex.Message}\");\n                throw;\n            }\n        }\n\n        /// <summary>\n        /// Start all service components with timeout protection\n        /// </summary>\n        public void Start()\n        {\n            if (!_stateLock.TryEnterWriteLock(OperationTimeout))\n            {\n                throw new TimeoutException(\"Failed to acquire write lock for starting service within timeout.\");\n            }\n\n            try\n            {\n                if (_isRunning)\n                    throw new InvalidOperationException(\"Service is already running.\");\n\n                try\n                {\n                    foreach (var component in _components)\n                    {\n                        try\n                        {\n                            var componentName = component.GetType().Name;\n                            component.Initialize();\n                            component.Start();\n                            Debug.WriteLine($\"Component started: {componentName}\");\n                        }\n                        catch (Exception ex)\n                        {\n                            Debug.WriteLine($\"Error starting component {component.GetType().Name}: {ex.Message}\");\n                            throw;\n                        }\n                    }\n\n                    // Start health check timer with non-blocking callback\n                    _healthCheckTimer = new Timer(PerformHealthCheck, null, HealthCheckInterval, HealthCheckInterval);\n                    _isRunning = true;\n                }\n                catch (Exception ex)\n                {\n                    Debug.WriteLine($\"Error starting service: {ex.Message}\");\n                    // Rollback: stop any started components\n                    foreach (var component in _components)\n                    {\n                        try\n                        {\n                            component.Stop();\n                        }\n                        catch { }\n                    }\n                    throw;\n                }\n            }\n            finally\n            {\n                _stateLock.ExitWriteLock();\n            }\n        }\n\n        /// <summary>\n        /// Stop all service components with timeout protection\n        /// </summary>\n        public void Stop()\n        {\n            if (!_stateLock.TryEnterWriteLock(OperationTimeout))\n            {\n                Debug.WriteLine(\"Warning: Failed to acquire write lock for stopping service within timeout. Proceeding anyway.\");\n                // Don't throw here - we need to stop regardless\n            }\n\n            try\n            {\n                if (!_isRunning)\n                    return;\n\n                try\n                {\n                    // Stop health check timer first\n                    _healthCheckTimer?.Dispose();\n                    _healthCheckTimer = null;\n\n                    // Stop all components in reverse order\n                    for (int i = _components.Count - 1; i >= 0; i--)\n                    {\n                        try\n                        {\n                            var componentName = _components[i].GetType().Name;\n                            \n                            // Use a separate thread with timeout for each component stop\n                            var stopTask = new Thread(() => _components[i].Stop())\n                            {\n                                Name = $\"Stop-{componentName}\",\n                                IsBackground = false\n                            };\n                            \n                            stopTask.Start();\n                            if (!stopTask.Join(5000)) // 5 second timeout per component\n                            {\n                                Debug.WriteLine($\"Warning: Component {componentName} stop operation timed out\");\n                                // Don't abort - let it finish in background\n                            }\n                            else\n                            {\n                                Debug.WriteLine($\"Component stopped: {componentName}\");\n                            }\n                        }\n                        catch (Exception ex)\n                        {\n                            Debug.WriteLine($\"Error stopping component {_components[i].GetType().Name}: {ex.Message}\");\n                        }\n                    }\n\n                    _isRunning = false;\n                }\n                catch (Exception ex)\n                {\n                    Debug.WriteLine($\"Error stopping service: {ex.Message}\");\n                    throw;\n                }\n            }\n            finally\n            {\n                if (_stateLock.IsWriteLockHeld)\n                {\n                    _stateLock.ExitWriteLock();\n                }\n            }\n        }\n\n        /// <summary>\n        /// Perform periodic health check on all components (non-blocking)\n        /// </summary>\n        private void PerformHealthCheck(object? state)\n        {\n            // Use read lock since we're only checking status\n            if (!_stateLock.TryEnterReadLock(5000))\n            {\n                Debug.WriteLine(\"Health check: Could not acquire read lock within 5 seconds, skipping this check.\");\n                return;\n            }\n\n            try\n            {\n                if (!_isRunning)\n                    return;\n\n                try\n                {\n                    foreach (var component in _components)\n                    {\n                        try\n                        {\n                            if (component is IHealthCheckable healthCheckable)\n                            {\n                                var health = healthCheckable.GetHealth();\n                                if (health.Status != HealthStatus.Status.Healthy)\n                                {\n                                    Debug.WriteLine($\"Warning: Component {component.GetType().Name} is {health.Status}. {health.Details}\");\n                                }\n                            }\n                        }\n                        catch (Exception ex)\n                        {\n                            Debug.WriteLine($\"Error checking health of {component.GetType().Name}: {ex.Message}\");\n                        }\n                    }\n                }\n                catch (Exception ex)\n                {\n                    Debug.WriteLine($\"Error during health check: {ex.Message}\");\n                }\n            }\n            finally\n            {\n                if (_stateLock.IsReadLockHeld)\n                {\n                    _stateLock.ExitReadLock();\n                }\n            }\n        }\n\n        /// <summary>\n        /// Get service status (thread-safe)\n        /// </summary>\n        public bool IsRunning\n        {\n            get\n            {\n                if (_stateLock.TryEnterReadLock(1000))\n                {\n                    try\n                    {\n                        return _isRunning;\n                    }\n                    finally\n                    {\n                        _stateLock.ExitReadLock();\n                    }\n                }\n                // If we can't acquire read lock within 1 second, assume running\n                return _isRunning;\n            }\n        }\n\n        /// <summary>\n        /// Dispose resources with timeout protection\n        /// </summary>\n        public void Dispose()\n        {\n            if (_disposed)\n                return;\n\n            try\n            {\n                Stop();\n                _healthCheckTimer?.Dispose();\n                _components.Clear();\n                _disposed = true;\n            }\n            catch (Exception ex)\n            {\n                Debug.WriteLine($\"Error during dispose: {ex.Message}\");\n            }\n            finally\n            {\n                _stateLock?.Dispose();\n            }\n        }\n    }\n}\n